<script setup lang="ts">
import {useHysRootAttrs} from '../../config'
const hysRootAttrs=useHysRootAttrs()
import {computed,toRef,ref,watch,onDeactivated,type CSSProperties} from 'vue';import {X} from 'lucide-vue-next';import {useDialog} from '../../composables/useDialog'
const props=withDefaults(defineProps<{open:boolean;title:string;width?:string;height?:string;closeOnMask?:boolean;closeOnEscape?:boolean;showClose?:boolean;destroyOnClose?:boolean;fullscreen?:boolean;placement?:'left'|'right'|'top'|'bottom';beforeClose?:(reason:'mask'|'escape'|'button')=>boolean|void|Promise<boolean|void>}>(),{width:'520px',closeOnMask:true,closeOnEscape:true,showClose:true,destroyOnClose:true,placement:'right'})
const emit=defineEmits<{close:[];closeError:[error:unknown]}>(),dialog=ref<HTMLElement>(),closing=ref(false)
const panelStyle=computed<CSSProperties>(()=>({...(props.fullscreen?{width:'100%',height:'100dvh',maxWidth:'100vw',maxHeight:'100dvh'}:props.placement==='top'||props.placement==='bottom'?{width:'100%',height:props.height||props.width,maxHeight:'100dvh'}:{width:props.width}), '--hys-ui-drawer-enter-x':props.placement==='left'?'-100%':props.placement==='right'?'100%':'0px','--hys-ui-drawer-enter-y':props.placement==='top'?'-100%':props.placement==='bottom'?'100%':'0px'}))
const {active,zIndex}=useDialog(toRef(props,'open'),dialog,()=>{if(props.closeOnEscape)void requestClose('escape')})
let epoch=0;function invalidateClose(){epoch++;closing.value=false}watch(()=>props.open,value=>{if(!value)invalidateClose()});onDeactivated(invalidateClose)
async function requestClose(reason:'mask'|'escape'|'button'='button'){if(closing.value||!props.open||!active.value)return;const token=++epoch;closing.value=true;try{if(props.beforeClose&&await props.beforeClose(reason)===false)return;if(active.value&&token===epoch)emit('close')}catch(error){if(active.value&&token===epoch)emit('closeError',error)}finally{if(token===epoch)closing.value=false}}
defineExpose({close:requestClose,element:dialog})
</script>
<template><Teleport to="body"><Transition name="hys-ui-drawer-motion"><div v-if="active&&(open||!destroyOnClose)" v-show="open" v-bind="hysRootAttrs" class="hys-ui-overlay hys-ui-drawer-overlay" :style="{zIndex}" :class="'hys-ui-drawer-'+placement" @pointerdown.self="closeOnMask&&requestClose('mask')"><aside ref="dialog" tabindex="-1" class="hys-ui-drawer" role="dialog" aria-modal="true" :aria-label="title" :aria-busy="closing" :style="panelStyle"><header class="hys-ui-dialog-head"><slot name="header"><h3>{{title}}</h3></slot><button v-if="showClose" type="button" class="hys-ui-icon-action" aria-label="关闭" :disabled="closing" @click="requestClose('button')"><X :size="18"/></button></header><div class="hys-ui-drawer-body"><slot/></div><footer v-if="$slots.footer" class="hys-ui-dialog-foot"><slot name="footer" :close="requestClose" :closing="closing"/></footer></aside></div></Transition></Teleport></template>
<style scoped>.hys-ui-drawer-left{justify-content:flex-start}.hys-ui-drawer-top{align-items:flex-start;justify-content:stretch}.hys-ui-drawer-bottom{align-items:flex-end;justify-content:stretch}.hys-ui-drawer-top .hys-ui-drawer,.hys-ui-drawer-bottom .hys-ui-drawer{position:relative}</style>
